import { mkdirSync, readFileSync, writeFileSync, statSync } from 'fs'; import { gzipSync } from 'zlib';
mkdirSync('dist/browser',{recursive:true});
const js=`(()=>{function e(n,d){window.dispatchEvent(new CustomEvent('adrunner:'+n,{detail:d}));fetch((window.AdRunner?.baseUrl||'')+'/v1/sites/'+encodeURIComponent(window.AdRunner?.siteId||'')+'/events',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'adrunner:'+n,detail:d})}).catch(()=>{})}function q(s){return document.querySelector('[data-ad-runner-slot="'+s.replace(/[^a-zA-Z0-9_-]/g,'\\$&')+'"]')}class R{constructor(siteId,baseUrl){this.siteId=siteId;this.baseUrl=baseUrl;this.mounted=new Set;this.history={}}async start(){if(this.manifest&&this.mounted.size)return;let b=await fetch(this.baseUrl+'/v1/sites/'+encodeURIComponent(this.siteId)+'/bootstrap.json').then(r=>r.json());this.manifest=await fetch(new URL(b.manifest,this.baseUrl).href).then(r=>r.json());for(const p of this.manifest.placements.filter(p=>p.enabled))await this.mount(p.anchor);e('ready',{site:this.siteId,version:this.manifest.version})}stop(){this.stopped=true}getStatus(){return{site:this.siteId,version:this.manifest?.version,mounted:[...this.mounted]}}getRouteHistory(s){return this.history[s]||[]}async refresh(s){const p=this.manifest.placements.find(p=>p.id===s||p.anchor===s);if(p){this.mounted.delete(p.id);let t=q(p.anchor);if(t)t.innerHTML='';await this.mount(s)}}async mount(s){const p=this.manifest?.placements.find(p=>p.id===s||p.anchor===s);if(!p||this.mounted.has(p.id))return;const t=q(p.anchor);if(!t){e('missing-slot',{site:this.siteId,placement:p.id,anchor:p.anchor});return}this.mounted.add(p.id);let attempts=[];e('slot-requested',{site:this.siteId,placement:p.id,anchor:p.anchor});for(let i=0;i<p.candidates.length;i++){let c=p.candidates[i],u=this.manifest.units[c.unit],n=this.manifest.networks[u.network],box=document.createElement('div');box.dataset.adRunnerCandidate=c.unit;t.appendChild(box);e('candidate-started',{site:this.siteId,placement:p.id,unit:c.unit,network:u.network,candidateIndex:i});let out=u.simulated_outcome||((n.adapter==='house-ad'||n.adapter==='direct-sponsor')?'filled':'unknown');let delay=Number(u.simulated_delay_ms||0);let start=performance.now();let result=await new Promise(r=>{let tm=setTimeout(()=>r('timeout'),c.timeout_ms);setTimeout(()=>{if(out!=='timeout'){clearTimeout(tm);r(out)}},delay)});let elapsedMs=Math.round(performance.now()-start);attempts.push({unit:c.unit,outcome:result,elapsedMs});e('candidate-'+result,{site:this.siteId,placement:p.id,unit:c.unit,network:u.network,candidateIndex:i,outcome:result,elapsedMs});if(result==='filled'){box.innerHTML=u.html|| (u.image_url?'<a href="'+(u.destination_url||'#')+'" target="_blank" rel="sponsored noopener"><img src="'+u.image_url+'" alt="'+(u.alt_text||'Advertisement')+'"></a>':'<div style="padding:1rem;background:#eef">'+(u.text||'Ad filled')+'</div>');[...t.children].forEach(x=>{if(x!==box)x.remove()});if(c.guaranteed)e('fallback-used',{site:this.siteId,placement:p.id,unit:c.unit});e('slot-filled',{site:this.siteId,placement:p.id,unit:c.unit,outcome:'filled'});this.history[p.anchor]=[...(this.history[p.anchor]||[]),{placement:p.id,filled:true,attempts}];return}else box.remove()}e('slot-collapsed',{site:this.siteId,placement:p.id});this.history[p.anchor]=[...(this.history[p.anchor]||[]),{placement:p.id,filled:false,attempts}]}}window.AdRunnerRuntime=R;let s=document.currentScript,site=s?.dataset.adRunnerSite,base=s?.dataset.adRunnerBase||(s?.src?new URL(s.src).origin:'');if(site){window.AdRunner=new R(site,base);window.AdRunner.start().catch(err=>e('manifest-error',{site,error:String(err)}))}})();`;
writeFileSync('dist/browser/ad-runner.js',js); writeFileSync('dist/browser/ad-runner.min.js',js.replace(/\s+/g,' ')); writeFileSync('dist/browser/ad-runner.min.js.map','{}');
